  "Let's start tomorrow.": "content/audio/let-s-start-tomorrow-31d897f1.m4a",
  "Let's forget about it.": "content/audio/let-s-forget-about-it-e26d86c3.m4a",
  "It's a slow morning. Have you ever worked somewhere this quiet?": "content/audio/it-s-a-slow-morning-have-you-ever-worked-5b233f01.m4a",
  "I've never worked somewhere this quiet.": "content/audio/i-ve-never-worked-somewhere-this-quiet-6e14ae62.m4a",
  "I like loud places.": "content/audio/i-like-loud-places-6fbef61b.m4a",
